(* [comment removed for export] *)
Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ ?M ?A _ => assert_fails (is_evar M); match goal with H : rw_cells _ M A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
          | |- u8arr _ ?M ?A _ => assert_fails (is_evar M); match goal with H : u8arr _ M A _ |- _ => exact H end
          end
        | eassumption ].
(* [comment removed for export] *)
Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;     (* [comment removed for export] *)
      change (Z.of_nat (cells_size cs)) with v
  end.
Local Tactic Notation "tr_keep" hyp(H) "over" hyp(MU) hyp(WM) "by" tactic3(tac) :=
  lazymatch type of MU with munch ?W ?m ?m' =>
  lazymatch type of H with
  | rw_cells _ _ ?A ?cs => apply (rw_cells_transport bsegs W m m' A cs) in H; [| exact MU| exact WM| fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | ro_cells _ _ ?A ?cs => apply (ro_cells_transport bsegs W m m' A cs) in H; [| exact MU| fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | bytes_at _ _ ?A ?bs => apply (bytes_at_transport bsegs W m m' A bs) in H; [| exact MU| cbn [disjoint_from fst snd]; tac]
  | u8arr _ _ ?A ?bs => apply (u8arr_transport bsegs W m m' A bs) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  | stk _ _ ?l ?h => apply (stk_transport_disjoint bsegs W m m' l h) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  end end.
(* [comment removed for export] *)
Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Ltac slia_atom := first [ exact I | assumption | match goal with K : chunk_disj _ _ _ _ |- _ => exact K end | dj_lia ].
Ltac slia_conj := first [ exact I | lazymatch goal with |- _ /\ _ => split; [slia_atom| slia_conj] end | slia_atom ].
Ltac slia ::= slia_conj.

(* [comment removed for export] *)
Ltac phase_close HH SD HC MU MUph WMph TRTAC DJTAC CATTAC INTOTAC :=
  tr_parked MUph WMph TRTAC; unfold parked in *;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?m4 _) =>
  lazymatch type of HC with AHttpCat _ ?g =>
    let SD4 := fresh "SD4" in let HC4 := fresh "HC4" in
    assert (SD4 := dof_side_step _ HH _ _ _ _ m4 _ _ _ _ _ _ _ _ SD MUph WMph ltac:(dwin_tac DJTAC));
    assert (HC4 : AHttpCat m4 g)
      by (eapply AHttpCat_transport; [exact HC| exact MUph| exact WMph| |]; cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; CATTAC);
    munch_into MU MUph INTOTAC; clear SD HC MUph WMph; rename SD4 into SD; rename HC4 into HC
  end end.

(* [comment removed for export] *)
Ltac park_chunks_but_shadow ff :=
  repeat match goal with
  | K : rw_cells _ _ ?a _ |- _ => lazymatch a with Z.shiftr ff 3 + 2147450880 => fail | _ => park K end
  | K : bytes_at _ _ _ _ |- _ => park K
  end.
Ltac tr_parked_sh MUsh WMsh TAC :=
  repeat match goal with
  | K : parked (rw_cells _ _ _ _) |- _ => unpark K; tr_keep K over MUsh WMsh by TAC
  | K : parked (bytes_at _ _ _ _) |- _ => unpark K; tr_keep K over MUsh WMsh by TAC
  end.
Ltac dedupe_chunks :=
  repeat match goal with K1 : rw_cells _ ?m ?a ?c, K2 : rw_cells _ ?m ?a ?c |- _ => clear K2 end;
  repeat match goal with K1 : bytes_at _ ?m ?a ?c, K2 : bytes_at _ ?m ?a ?c |- _ => clear K2 end.

Lemma rw_cells_CB_length' {HCEIL : HeapCeil} : forall m A n bs, rw_cells bsegs m A [CB n bs] -> length bs = n.
Proof. intros m A n bs [[Hwf _] _]. cbn in Hwf. destruct Hwf as [L _]. exact L. Qed.

